void print_poly(const char *name, const poly *v)
{
	printf("const static uint32_t %s[%d] = {", name, KYBER_N);
	for (int j = 0; j < KYBER_N; j++)
	{
		printf("0x%04x", v[0].coeffs[j] >= 0 ? v[0].coeffs[j] % KYBER_Q : (v[0].coeffs[j] % KYBER_Q + KYBER_Q) % KYBER_Q);
		if (j < KYBER_N-1)
		{
			printf(",");
		}
	}
  	printf("};\n");
}

void print_polyvec(const char *name, const polyvec *v)
{
	printf("const static uint32_t %s[%d][%d] = {\n", name, KYBER_K, KYBER_N);
  for (int i = 0; i < KYBER_K; i++)
  {
	printf("{");
	for (int j = 0; j < KYBER_N; j++)
	{
		printf("0x%04x", v[0].vec[i].coeffs[j] >= 0 ? v[0].vec[i].coeffs[j] % KYBER_Q : (v[0].vec[i].coeffs[j] % KYBER_Q + KYBER_Q) % KYBER_Q);
		if (j < KYBER_N-1)
		{
			printf(",");
		}
	}
	printf("}");
	if (i < KYBER_K-1)
	{
		printf(",\n");
	}
  }
  printf("};\n");
}

void print_byte_array(const char *name, const uint8_t *arr, size_t len)
{
	printf("const static uint8_t %s[%d] = {", name, len);
	for(size_t i = 0; i < len; ++i) {
		printf("0x%02x", arr[i]);
		if (i < len-1)
		{
			printf(",");
		}
	}
	printf("};\n");
}

